def _recheck_claims_naming(self, path: str, content: bytes) -> None:
    """A file that mentions a changed callee but was not part of the claim about it is a
    call site that did not exist when the claim was made — a caller just written, or one
    typed into a file the engine had never seen.

    Staleness cannot catch this: the claim never depended on this file, so nothing marks it
    stale, and it would go on reporting the call sites that existed at the time. So the
    defining file is re-judged instead, which re-runs the search over current content.
    """
    for rec in self.evid.records():
        if rec["status"] != "fresh" or rec["kind"] not in ("signature_change", "removed_function"):
            continue
        if path in rec["based_on"]:
            continue                      # already part of the claim: staleness handles it
        name = rec["key"].rsplit(":", 1)[-1].split(".")[-1]
        if name == "-" or name.encode() not in content:
            continue
        defining = rec["key"].split(":", 2)[1]
        if (rev := self.view.effective(defining)) is not None:
            self.log(f"  {path} now names {name}: re-judging {rec['title']}")
            self.sched.submit(defining, rev.sha, self.seq, rev.origin)

def _candidates(self, name: str) -> list[str]:
    """Files that might call `name`. Live: rg over the working tree, plus any buffer with
    unsaved content — rg reads files, so a call typed a second ago is invisible to it.
    Replay: scan the latest snapshot of every known path."""
    if self.replay:
        return [r for r in self.snap.known_paths() if name.encode() in (self._read_current(r) or b"")]
    found = {self.rel(str(p)) for p in callers.candidates(self.root, name)}
    for rel in self.view.dirty_paths():
        body = self.view.read(rel)
        if body and name.encode() not in body:
            found.add(rel)
    return sorted(found)

def read(self, path: str) -> bytes | None:
    """The effective bytes for a path: overlay first, then disk."""
    rev = self.effective(path)
    if rev is not None:
        body = self.snap.get(rev.sha)
        if body is not None:
            return body
    if self.replay:
        latest = self.snap.latest(path)
        return self.snap.get(latest) if latest else None
    p = self.root / path
    try:
        return p.read_bytes() if p.exists() else None
    except OSError:
        return None

def _load(self) -> None:
    if not self.path.exists():
        return
    try:
        d = json.loads(self.path.read_text())
    except (ValueError, OSError):
        return
    self.session = d.get("session")
    self.overlay = {k: Revision(**v) for k, v in d.get("overlay", {}).items()
                    if self.snap.has(v.get("sha", ""))}
    self.diagnostics = d.get("diagnostics", {})

def __init__(self, root: Path, snap: SnapshotStore, state_dir: Path, replay: bool = False):
    self.root = root
    self.snap = snap
    self.replay = replay
    self.path = state_dir / "view.json"
    self.overlay: dict[str, Revision] = {}
    self.session: str | None = None
    self.diagnostics: dict[str, list[dict]] = {}
    self._load()

def end_session(self, session: str | None) -> list[str]:
    """That editor is gone, and its unsaved buffers went with it. The effective revision
    of each affected path falls back to the file on disk. Returns those paths so the
    caller can re-judge them: claims derived from content that no longer exists anywhere
    must not be left standing."""
    dropped = [p for p, r in self.overlay.items()
               if session is None or r.session is None or r.session == session]
    for p in dropped:
        del self.overlay[p]
    if session is None or session == self.session:
        self.session = None
    return sorted(dropped)

def matches(self, other: "Source | None") -> bool:
    """Same file, not merely a file at the same path. `size` plays no part: a file that has
    only grown is still the same file, and that is the common case. `head_len == 0` means
    there was nothing to fingerprint yet (nothing had been read); device and inode alone
    decide, since comparing two empty hashes would otherwise vacuously agree for any file."""
    if other is None or self.device != other.device or self.inode != other.inode:
        return False
    if self.head_len == 0 or other.head_len == 0:
        return True
    return self.head_sha == other.head_sha

def follow(self, stop: threading.Event | None = None, poll_s: float = 0.2) -> Iterator[tuple[ev.Event, int]]:
    """Yield (event, offset_after_this_line) forever, starting from the stored offset and
    skipping events already accepted. Blocking."""
    while True:
        yield from self._scan()
        if stop is not None:
            if stop.wait(poll_s):
                return
        else:
            time.sleep(poll_s)

