@pytest.fixture
def project(tmp_path):
    (tmp_path / "calc.py").write_text(SAVED)
    (tmp_path / "client.py").write_text(CLIENT)
    eng = Engine(tmp_path, run_tests=False, log=lambda _: None)
    for name in ("calc.py", "client.py"):
        eng.handle_event(Event(kind="buffer_saved", path=name))
    eng.sched.drain(wait=False)
    return eng, tmp_path

def drain(self, wait: bool = True) -> int:
    """Run everything due. In replay (wait=False) runs immediately, in order."""
    ran = 0
    while True:
        with self._lock:
            if not self._pending:
                return ran
            p = next(iter(self._pending.values()))
            if wait and p.due > time.time():
                delay = p.due - time.time()
            else:
                self._pending.pop(p.path)
                delay = None
        if delay is not None:
            time.sleep(delay)
            continue
        self.stats["ran"] += 1
        self.run(p.path, p.sha, p.seq, p.cancelled_shas, p.origin)
        ran += 1

