def matches(self, other: "Source | None") -> bool:
    """Same file, not merely a file at the same path. `size` plays no part: a file that has
    only grown is still the same file, and that is the common case. `head_len == 0` means
    there was nothing to fingerprint yet (nothing had been read); device and inode alone
    decide, since comparing two empty hashes would otherwise vacuously agree for any file."""
    if other is None or self.device != other.device or self.inode != other.inode:
        return False
    if self.head_len == 0 or other.head_len == 0:
        return True
    return self.head_sha == other.head_sha

def suggest(evidence_text: str, model: str, backend: str = "ollama", base_url: str | None = None,
            timeout_s: float = 30, num_ctx: int = 4096, cpu_only: bool = False,
            keep_alive: str = "30m") -> Reply:
    t0 = time.time()
    try:
        if backend == "ollama":
            url = (base_url or "http://127.0.0.1:11434") + "/api/chat"
            opts = {"num_ctx": num_ctx, "temperature": 0, "num_predict": 60}
            if cpu_only:
                opts["num_gpu"] = 0
            # Ollama evicts after five minutes by default. Measured on this host, a cold load of
            # qwen3-coder:30b is 15.437 s against ~1.66 s warm, so with the default the developer
            # pays the cold load on most saves after a pause -- which is the difference between a
            # companion and an interruption. llama-server keeps the model resident already, so
            # this is an ollama-only concern.
            body = {"model": model, "stream": False, "think": False, "options": opts,
                    "keep_alive": keep_alive,
                    "messages": [{"role": "system", "content": SYSTEM}, {"role": "user", "content": evidence_text}]}
            req = urllib.request.Request(url, data=json.dumps(body).encode(), headers={"Content-Type": "application/json"})
            with urllib.request.urlopen(req, timeout=timeout_s) as r:
                d = json.loads(r.read())
            return Reply(d["message"]["content"].strip(), "ok", time.time() - t0,
                         d.get("prompt_eval_count"), d.get("eval_count"),
                         (d.get("prompt_eval_duration") or 0) / 1e9, (d.get("eval_duration") or 0) / 1e9, model)
        else:
            url = (base_url or "http://127.0.0.1:8080") + "/v1/chat/completions"
            body = {"model": model, "temperature": 0, "max_tokens": 60,
                    "messages": [{"role": "system", "content": SYSTEM}, {"role": "user", "content": evidence_text}]}
            req = urllib.request.Request(url, data=json.dumps(body).encode(), headers={"Content-Type": "application/json"})
            with urllib.request.urlopen(req, timeout=timeout_s) as r:
                d = json.loads(r.read())
            u = d.get("usage", {})
            tm = d.get("timings", {})
            return Reply(d["choices"][0]["message"]["content"].strip(), "ok", time.time() - t0,
                         u.get("prompt_tokens"), u.get("completion_tokens"),
                         (tm.get("prompt_ms") or 0) / 1e3 or None, (tm.get("predicted_ms") or 0) / 1e3 or None, model)
    except urllib.error.URLError as e:
        st = "timeout" if "timed out" in str(e).lower() else "unavailable"
        return Reply(None, st, time.time() - t0, model=model)
    except TimeoutError:
        return Reply(None, "timeout", time.time() - t0, model=model)
    except Exception as e:  # noqa: BLE001
        return Reply(None, f"error: {type(e).__name__}", time.time() - t0, model=model)

def run_for(root: Path, names: list[str], timeout_s: float = 60) -> TestResult:
    def mentions(p: Path) -> bool:
        b = p.read_bytes()
        return any(n.encode() in b for n in names)
    files = sorted({str(p) for pat in ("test_*.py", "*_test.py") for p in root.rglob(pat)
                    if ".companion" not in p.parts and mentions(p)})
    if not files:
        return TestResult("none", f"no test file mentions {', '.join(names)}", [])
    cmd = _pytest_cmd()
    if cmd is None:
        return TestResult("unavailable", "pytest not importable in this interpreter", files)
    try:
        r = subprocess.run(cmd + ["-q", "-x", "--no-header", "-p", "no:cacheprovider", *files],
                           cwd=root, capture_output=True, text=True, timeout=timeout_s)
    except subprocess.TimeoutExpired:
        return TestResult("timeout", f"pytest exceeded {timeout_s}s", files)
    tail = "\n".join((r.stdout + r.stderr).strip().splitlines()[-12:])
    last = tail.splitlines()[-1] if tail else ""
    return TestResult("passed" if r.returncode == 0 else "failed", last, files, tail)

def end_session(self, session: str | None) -> list[str]:
    """That editor is gone, and its unsaved buffers went with it. The effective revision
    of each affected path falls back to the file on disk. Returns those paths so the
    caller can re-judge them: claims derived from content that no longer exists anywhere
    must not be left standing."""
    dropped = [p for p, r in self.overlay.items()
               if session is None or r.session is None or r.session == session]
    for p in dropped:
        del self.overlay[p]
    if session is None or session == self.session:
        self.session = None
    return sorted(dropped)

def disk_revision(self, path: str) -> Revision | None:
    sha = self.snap.latest(path, ON_DISK)
    if sha:
        return Revision(sha, "disk")
    if self.replay:
        return None
    p = self.root / path
    if p.exists():
        try:
            return Revision(sha_of(p.read_bytes()), "disk")
        except OSError:
            return None
    return None
